#include <iostream>
#include <vector>
using namespace std;

typedef vector<long long> vec;
typedef vector<vec> mat;

long long N; int K;
mat R[40];
mat D[100][40];

void initialize_matrix(mat& A, int rows, int cols) {
    A.resize(rows);
    for (int i = 0; i < rows; ++i) A[i].assign(cols, 0);
}

mat multiply_matrices(const mat& A, const mat& B) {
    mat C(A.size(), vec(B[0].size(), 0));
    for (size_t i = 0; i < A.size(); ++i)
        for (size_t j = 0; j < B[0].size(); ++j)
            for (size_t k = 0; k < B.size(); ++k)
                C[i][j] += A[i][k] * B[k][j];
    return C;
}

int main() {
    cin >> N >> K;
    int count = 0; long long power = 1;
    while (power <= N) { power *= K; count++; }
    power /= K;
    vector<int> digits(count);
    for (int i = 0; i < count; ++i) {
        digits[i] = N / power;
        N %= power;
        power /= K;
    }
    for (int i = 0; i <= K; ++i) initialize_matrix(R[i], K + 1, K + 1);
    for (int i = 0; i <= count; ++i)
        for (int j = 0; j < K; ++j) initialize_matrix(D[i][j], K + 1, K + 1);
    R[0][K][K] = 1; R[1][K][K] = 1;
    for (int j = 0; j < K; ++j) R[0][j][j] = 1;
    for (int j = 0; j < K; ++j) R[1][(j + K - 1) % K][j] = 1;
    for (int j = 2; j <= K; ++j) R[j] = multiply_matrices(R[j - 1], R[1]);
    for (int j = 0; j <= K; ++j) {
        D[0][0][j][j] = 1;
        D[0][0][j][0] = 1;
    }
    int total_count = count;
    for (int i = 0; i <= total_count; ++i) {
        for (int j = 1; j < K; ++j) {
            D[i][j] = multiply_matrices(multiply_matrices(R[K - j], D[i][0]), R[j]);
        }
        if (i + 1 <= total_count) D[i + 1][0] = D[i][K - 1];
    }
    mat answer(1, vec(K + 1, 0)); answer[0][K] = 1;
    int mod_acc = 0;
    for (int i = 0; i < total_count; ++i) {
        if (digits[i] != 0)
            answer = multiply_matrices(multiply_matrices(R[K - mod_acc], D[total_count - i - 1][digits[i] - 1]), R[mod_acc]);
        mod_acc += digits[i]; mod_acc %= K;
    }
    long long total_res = 0;
    for (int i = 0; i <= K; ++i) total_res += answer[0][i];
    cout << total_res << endl;
}
